import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor matvec_forward(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <int THREADS, int BLOCK_M, int BLOCK_K>
__global__ void matvec_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int K, int split_size)
{
  int block_row_start = blockIdx.x * BLOCK_M;
  int tid = threadIdx.x;
  int k_start = blockIdx.y * split_size;
  int k_end = K < (k_start + split_size) ? K : (k_start + split_size);
  // Double-buffered shared memory staging area for the B chunk. Two
  // BLOCK_K-sized buffers allow the next chunk's global-memory load to be
  // issued and overlapped with the compute (A loads + FMA) of the currently
  // resident chunk, hiding global memory latency via software pipelining.
  extern __shared__ float sB[];
  float* sB_buf0 = sB;
  float* sB_buf1 = sB + BLOCK_K;
  float sum[BLOCK_M];
  #pragma unroll
  for (int r = 0; r < BLOCK_M; r++) sum[r] = 0.0f;
  auto load_chunk = [&](int k0, float* dst) {
    int chunk = (k_end - k0 < BLOCK_K) ? (k_end - k0) : BLOCK_K;
    int chunk4 = chunk & ~3;
    int i4 = tid * 4;
    for (; i4 + 3 < chunk4; i4 += THREADS * 4) {
      float4 bv = *reinterpret_cast<const float4*>(&B[k0 + i4]);
      *reinterpret_cast<float4*>(&dst[i4]) = bv;
    }
    for (int i = chunk4 + tid; i < chunk; i += THREADS) {
      dst[i] = B[k0 + i];
    }
  };
  int cur_buf = 0;
  if (k_start < k_end) {
    load_chunk(k_start, sB_buf0);
    __syncthreads();
  }
  for (int k0 = k_start; k0 < k_end; k0 += BLOCK_K) {
    int chunk = (k_end - k0 < BLOCK_K) ? (k_end - k0) : BLOCK_K;
    int chunk4 = chunk & ~3;
    int next_k0 = k0 + BLOCK_K;
    float* sBc = (cur_buf == 0) ? sB_buf0 : sB_buf1;
    float* sBn = (cur_buf == 0) ? sB_buf1 : sB_buf0;
    // Prefetch the next chunk of B into the other buffer while the
    // current chunk is still being consumed below.
    if (next_k0 < k_end) {
      load_chunk(next_k0, sBn);
    }
    // Vectorized accumulation: load A in float4 chunks (coalesced across threads
    // since consecutive tids access consecutive 16B-aligned segments), and reuse
    // the shared B chunk across BLOCK_M rows of A.
    int j4 = tid * 4;
    for (; j4 + 3 < chunk4; j4 += THREADS * 4) {
      float4 bval4 = *reinterpret_cast<const float4*>(&sBc[j4]);
      int k = k0 + j4;
      #pragma unroll
      for (int r = 0; r < BLOCK_M; r++) {
        int row = block_row_start + r;
        if (row < M) {
          float4 aval4 = *reinterpret_cast<const float4*>(&A[(size_t)row * K + k]);
          sum[r] += aval4.x * bval4.x + aval4.y * bval4.y +
                    aval4.z * bval4.z + aval4.w * bval4.w;
        }
      }
    }
    for (int i = chunk4 + tid; i < chunk; i += THREADS) {
      float bval = sBc[i];
      int k = k0 + i;
      #pragma unroll
      for (int r = 0; r < BLOCK_M; r++) {
        int row = block_row_start + r;
        if (row < M) {
          sum[r] += A[(size_t)row * K + k] * bval;
        }
      }
    }
    // Synchronize so that (a) the prefetch into sBn is complete before it
    // becomes the current buffer next iteration, and (b) all threads are
    // done reading sBc before it is overwritten two iterations from now.
    __syncthreads();
    cur_buf ^= 1;
  }
  int lane = tid & 31;
  int wid  = tid >> 5;
  __shared__ float shared_reduce[BLOCK_M][THREADS / 32];
  #pragma unroll
  for (int r = 0; r < BLOCK_M; r++) {
    float v = sum[r];
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      v += __shfl_down_sync(0xffffffff, v, offset);
    }
    if (lane == 0) shared_reduce[r][wid] = v;
  }
  __syncthreads();
  if (wid == 0) {
    #pragma unroll
    for (int r = 0; r < BLOCK_M; r++) {
      float v = (lane < (THREADS / 32)) ? shared_reduce[r][lane] : 0.0f;
      #pragma unroll
      for (int offset = (THREADS / 32) / 2; offset > 0; offset >>= 1) {
        v += __shfl_down_sync(0xffffffff, v, offset);
      }
      if (lane == 0) {
        int row = block_row_start + r;
        if (row < M) {
          // Split-K reduction: multiple blocks along blockIdx.y accumulate
          // partial dot-products for the same output row into C via atomicAdd.
          atomicAdd(&C[row], v);
        }
      }
    }
  }
}
torch::Tensor matvec_forward(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2, "A must be 2D (M, K)");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");
  int M = (int)A.size(0);
  int K = (int)A.size(1);
  auto B_flat = B.reshape({-1});
  TORCH_CHECK(B_flat.numel() == K, "B must have K elements");
  auto A_c = A.contiguous();
  auto B_c = B_flat.contiguous();
  auto C = torch::zeros({M, 1}, A.options());
  constexpr int THREADS = 256;
  constexpr int BLOCK_M = 16;
  constexpr int BLOCK_K = 1024;
  // Split-K: the reduction dimension K is very large (>1M elements) relative
  // to M, so a single block would need a long sequential loop over K. Splitting
  // K across multiple blocks (grid.y) increases the number of concurrently
  // resident blocks/warps, improving memory-level parallelism and SM
  // utilization. Partial sums are combined via atomicAdd into a zero-
  // initialized output tensor.
  constexpr int NUM_SPLITS = 8;
  int split_size = (K + NUM_SPLITS - 1) / NUM_SPLITS;
  dim3 block(THREADS);
  dim3 grid((unsigned)((M + BLOCK_M - 1) / BLOCK_M), (unsigned)NUM_SPLITS);
  size_t smem_bytes = 2 * BLOCK_K * sizeof(float);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  matvec_kernel<THREADS, BLOCK_M, BLOCK_K><<<grid, block, smem_bytes, stream>>>(
      A_c.data_ptr<float>(),
      B_c.data_ptr<float>(),
      C.data_ptr<float>(),
      M, K, split_size
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "matvec_kernel launch failed: ", cudaGetErrorString(err));
  return C;
}
"""

matvec_ext = load_inline(
    name="cute_matvec_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["matvec_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix-vector multiplication (C = A * B) implemented with a custom
    CuTe-based CUDA kernel. Each CUDA block computes one output element
    (dot product of a row of A with B) using vectorized float4 loads
    and a two-stage (warp + block) reduction.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = matvec_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.matvec_forward(A, B)

